target:
logWorkoutBtn = Button(
  label="Log Workout",
  icon="plus",
  variant="default",
  on={press: Event("log_workout")}
)

topBarActions = Box(
  style={display: "flex", flexDirection: "row", alignItems: "center", gap: 14},
  children=[searchBox, logWorkoutBtn, profileAvatarWrap]
)

$/library/filter = "all"

libraryHeader = Stack(
  direction="horizontal",
  align="center",
  justify="between",
  children=[
    Heading(text="New in your library", level="h3"),
    Segmented(
      items=[
        {label: "All", value: "all"},
        {label: "Unplayed", value: "unplayed"},
        {label: "Downloaded", value: "downloaded"}
      ],
      value=$/library/filter,
      variant="segmented",
      size="sm",
      on={change: Event("filter_library", {filter: $/library/filter})}
    )
  ]
)
